using System.Security.Cryptography; using CareComply.Application.Abstractions.Clients; using CareComply.Application.Abstractions.Tenancy; using CareComply.Domain.Clients; using CareComply.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace CareComply.Infrastructure.Clients;
internal sealed class EfClientHospitalizationStore(CareComplyDbContext db, ITenantScopeAccessor tenantScopeAccessor) : IClientHospitalizationStore
{
 public async Task<HospitalizationList?> List(Guid id,CancellationToken ct) { if(!await CanAccessClient(id,ct))return null; var rows=await db.ClientHospitalizations.AsNoTracking().Where(x=>x.ClientId==id).OrderByDescending(x=>x.AdmittedAtUtc).ToArrayAsync(ct); return new(rows.Select(Map).ToArray()); }
 public async Task<HospitalizationMutation> Create(HospitalizationCreate r,CancellationToken ct) { if(!await CanAccessClient(r.ClientId,ct))return new(HospitalizationMutationStatus.ClientNotFound); var x=ClientHospitalization.Create(Guid.CreateVersion7(),r.ClientId,r.HospitalName,r.AdmittedAtUtc,r.DischargedAtUtc,r.Reason,r.Diagnosis,r.DischargeInstructions,r.ActorId,r.NowUtc); db.ClientHospitalizations.Add(x); await db.SaveChangesAsync(ct); return new(HospitalizationMutationStatus.Succeeded,Map(x)); }
 public async Task<HospitalizationMutation> Update(HospitalizationUpdate r,CancellationToken ct) { if(!await CanAccessClient(r.ClientId,ct))return new(HospitalizationMutationStatus.ClientNotFound); var x=await db.ClientHospitalizations.SingleOrDefaultAsync(x=>x.Id==r.Id&&x.ClientId==r.ClientId,ct); if(x is null)return new(HospitalizationMutationStatus.NotFound); if(!string.Equals(Version(x.RowVersion),r.EditorVersion,StringComparison.OrdinalIgnoreCase))return new(HospitalizationMutationStatus.Conflict); x.Update(r.HospitalName,r.AdmittedAtUtc,r.DischargedAtUtc,r.Reason,r.Diagnosis,r.DischargeInstructions,r.NowUtc); try{await db.SaveChangesAsync(ct);}catch(DbUpdateConcurrencyException){return new(HospitalizationMutationStatus.Conflict);} return new(HospitalizationMutationStatus.Succeeded,Map(x)); }
 private async Task<bool> CanAccessClient(Guid clientId,CancellationToken ct) { var tenant=await tenantScopeAccessor.GetAsync(ct); return tenant is not null && await db.Clients.AsNoTracking().AnyAsync(x=>x.Id==clientId&&(tenant.IsPlatformAdministrator||x.CompanyId==tenant.CompanyId),ct); }
 private static HospitalizationItem Map(ClientHospitalization x)=>new(x.Id,x.HospitalName,x.AdmittedAtUtc,x.DischargedAtUtc,x.Reason,x.Diagnosis,x.DischargeInstructions,Version(x.RowVersion));
 private static string Version(byte[] value)=>Convert.ToHexString(SHA256.HashData(value));
}
